#!/usr/bin/env python3
# ═══════════════════════════════════════════════════════════════════════
#  GENERATED by JaxCodegen.generateShim — do not edit by hand.
#  ImageNet batch shim: the SAME tfds/tf.data pipeline `ResNet-50 (ImageNet)`'s JAX
#  reference trainer consumes, streamed to stdout for the verified XLA trainer.
#
#  Wire format — a 16-byte preamble once, then one record per batch:
#      preamble : b'LMSH' | int32 version=3 | int32 batch | int32 flat_len
#                 (version=4 appends | int32 nclasses, for soft targets)
#      record   : int32 rows | int32[rows] labels | float32[rows*flat_len] images (CHW, norm)
#  `rows` <= batch, and it is EXPLICIT because a partial final batch (drop_remainder=False on
#  the val split, so all 50,000 images are scored) cannot be recovered from read lengths: a
#  pipe does not preserve write boundaries, so a reader inferring the count from a short label
#  read walks into the image block. v1/v2 had no count and did exactly that.
#  The preamble exists so a shape mismatch fails LOUDLY at the reader instead of
#  silently misaligning every subsequent batch (the shim's G4).
#
#  env: SHIM_BATCH (default 256), SHIM_SPLIT (train|validation), SHIM_SEED (default 0),
#       SHIM_HASH=<n>  -> hash n batches to stderr and exit, streaming nothing
#       SHIM_NCLASSES=K -> wire v2: float32[B,K] target distributions instead of int32[B]
#       SHIM_MIX=off|mixup|cutmix|both  -> mixup/cutmix on the PRODUCER side (needs v2).
#                       'both' alternates per step, as the reference does. Default is this
#                       config's own useMixup/useCutmix. SHIM_MIXUP_ALPHA / SHIM_CUTMIX_ALPHA
#                       override the Beta shapes. ⚠ The lambda stream is numpy's, NOT the
#                       reference's jax.random one — same distribution, different numbers.
#       TFDS_DATA_DIR  -> the prepared tfds tree (default ~/tensorflow_datasets)
# ═══════════════════════════════════════════════════════════════════════

import os, sys, hashlib
import numpy as np

_SHIM_SEED = int(os.environ.get('SHIM_SEED', '0'))
os.environ.setdefault('AUG_SEED', str(_SHIM_SEED + 1))  # non-zero: TF rejects 0 under determinism

# ═══════════════════════════════════════════════════════════════════════
#  ImageNet streaming pipeline (tfds + tf.data)
# ═══════════════════════════════════════════════════════════════════════

import tensorflow as tf
tf.config.set_visible_devices([], 'GPU')  # keep TF off the GPUs
import tensorflow_datasets as tfds

_IMG_SIZE = 224
_CROP_PADDING = 32
_CROP_PCT = 0.875000   # explicit test crop ratio (timm resnet50.a1/a2/a3_in1k = 0.95)
_TRAIN_SIZE = 224   # RSB-A3 train resolution; eval stays _IMG_SIZE (forward infers from flat len)
_MEAN_RGB = tf.constant([0.485 * 255, 0.456 * 255, 0.406 * 255], dtype=tf.float32)
_STD_RGB  = tf.constant([0.229 * 255, 0.224 * 255, 0.225 * 255], dtype=tf.float32)
_AUG_SEED = os.environ.get('AUG_SEED')
_AUG_SEED = int(_AUG_SEED) if _AUG_SEED else None

_RA_INC = True   # timm inc1 (gap D)

def _imagenet_decode_random_crop_flip(image_bytes):
    shape = tf.io.extract_jpeg_shape(image_bytes)
    bbox = tf.constant([0.0, 0.0, 1.0, 1.0], dtype=tf.float32, shape=[1, 1, 4])
    bbox_begin, bbox_size, _ = tf.image.sample_distorted_bounding_box(
        shape, bounding_boxes=bbox,
        min_object_covered=0.1, aspect_ratio_range=(3./4, 4./3.),
        area_range=(0.08, 1.0), max_attempts=10,
        seed=_AUG_SEED,
        use_image_if_no_bounding_boxes=True)
    oy, ox, _ = tf.unstack(bbox_begin)
    th, tw, _ = tf.unstack(bbox_size)
    window = tf.stack([oy, ox, th, tw])
    img = tf.io.decode_and_crop_jpeg(image_bytes, window, channels=3)
    img = tf.image.resize([img], [_TRAIN_SIZE, _TRAIN_SIZE],
                          method=tf.image.ResizeMethod.BICUBIC, antialias=True)[0]
    img = tf.image.random_flip_left_right(img, seed=_AUG_SEED)
    return img

def _imagenet_decode_center_crop(image_bytes):
    img = tf.io.decode_jpeg(image_bytes, channels=3)
    shape = tf.shape(img)
    h, w = shape[0], shape[1]
    target = tf.cast(tf.round(_IMG_SIZE / _CROP_PCT), tf.int32)
    scale = tf.cast(target, tf.float32) / tf.cast(tf.minimum(h, w), tf.float32)
    nh = tf.cast(tf.round(tf.cast(h, tf.float32) * scale), tf.int32)
    nw = tf.cast(tf.round(tf.cast(w, tf.float32) * scale), tf.int32)
    img = tf.image.resize(img, [nh, nw], method=tf.image.ResizeMethod.BICUBIC,
                          antialias=True)   # PIL-equivalent; see the emitter's note
    oy = (nh - _IMG_SIZE) // 2
    ox = (nw - _IMG_SIZE) // 2
    return tf.image.crop_to_bounding_box(img, oy, ox, _IMG_SIZE, _IMG_SIZE)

def build_imagenet_iter(split, batch_size, training, augment, shard=None):
    ds = tfds.load('imagenet2012', split=split,
                   decoders={'image': tfds.decode.SkipDecoding()},
                   data_dir=os.environ.get('TFDS_DATA_DIR'))
    if shard is not None:
        ds = ds.shard(num_shards=shard[1], index=shard[0])
    def _pp(ex):
        b = ex['image']
        img = (_imagenet_decode_random_crop_flip(b)
               if (training and augment)
               else _imagenet_decode_center_crop(b))
        img = tf.cast(img, tf.float32)              # 0..255 HWC
        img = (img - _MEAN_RGB) / _STD_RGB          # normalize, still HWC
        img = tf.transpose(img, [2, 0, 1])          # HWC -> CHW
        img = tf.reshape(img, [-1])  # flat; forward infers res (train _TRAIN_SIZE / eval _IMG_SIZE)
        return img, ex['label']
    if training:
        ds = ds.shuffle(8192, seed=42, reshuffle_each_iteration=True)
        ds = ds.repeat()
    ds = ds.map(_pp, num_parallel_calls=tf.data.AUTOTUNE)
    ds = ds.batch(batch_size, drop_remainder=training)
    ds = ds.prefetch(tf.data.AUTOTUNE)
    return tfds.as_numpy(ds)

def prefetch_to_device(it, sharding, depth=2):
    # Overlap host->device copies with compute: device_put is async, so
    # keeping `depth` batches in flight hides the H2D transfer behind the
    # previous train_step instead of serializing after it.
    q = collections.deque()
    for x, y in it:
        q.append((jax.device_put(x, sharding), jax.device_put(y, sharding)))
        if len(q) >= depth:
            yield q.popleft()
    while q:
        yield q.popleft()


def _main():
    batch    = int(os.environ.get('SHIM_BATCH', '256'))
    split    = os.environ.get('SHIM_SPLIT', 'train')
    seed     = _SHIM_SEED
    hash_n   = int(os.environ.get('SHIM_HASH', '0'))
    training = (split == 'train')
    # Determinism, and it takes all three of these. MEASURED: with only set_seed, two runs at
    # the same seed hash DIFFERENTLY — the crop/flip ops draw from TF's global state and
    # num_parallel_calls=AUTOTUNE makes the draw order vary. enable_op_determinism then REFUSES
    # to run sample_distorted_bounding_box without a non-zero op-level seed, which is what
    # AUG_SEED supplies (installed above, at module scope). Verify with SHIM_HASH, do not assume.
    #
    # ⚠ IT IS EXPENSIVE IN ISOLATION AND FREE IN SITU, AND THE SECOND HALF IS WHY IT STAYS ON.
    # `enable_op_determinism()` serializes the tf.data map: MEASURED 2026-08-11 on ares (ViT shim,
    # bs128, marginal over 100 batches, SHIM_HASH so no transport is involved) — 120 img/s at
    # 116-125% CPU with it ON against 639 img/s at 386-470% CPU with it OFF. 5.3x, and the CPU%
    # is the mechanism: a 32-core box runs this pipeline on ~1.2 cores under determinism and ~4.7
    # without. `enable_op_determinism` is emitted HERE and nowhere else, so the JAX reference
    # trainer this shim mirrors has never paid it.
    #
    # ⛔ AND YET IT DOES NOT MOVE THE STEP. Same day, ViT/ImageNet 4x bs128 end-to-end: 567 ms/step
    # with determinism ON, 592 OFF — i.e. nothing, at 5.3x the producer speed. The producer was
    # never the binding constraint; the consumer was reading ONE handle at a time while the other
    # seven producers slept in write() (70% of the box idle). The real fix was depth-n prefetch
    # (`LeanMlir/VerifiedTrain.lean`, 567 -> 287 ms/step), and it is orthogonal to this line.
    # ▶ THE LESSON, since it cost a session: an isolated component measurement (SHIM_HASH) tells
    # you a component's CAPACITY, not what limits the pipeline. Capacity is irrelevant when the
    # consumer pulls one batch and walks away.
    #
    # ▶ So the default STAYS ON, for two reasons that survive the measurement: it costs nothing
    # end-to-end, and `tests/prefetch_tie.sh`'s A1-vs-A2 control needs a REPLAYABLE producer
    # stream — turning this off makes that control fail and every verdict downstream unreadable.
    # What determinism buys is replay, not fidelity: the ops, magnitudes, probabilities and policy
    # are identical either way and only the ORDER of random draws moves. SHIM_DETERMINISM=0 opts
    # out (for a producer-bound net, should one ever be measured); =1 forces it on.
    _det_env = os.environ.get('SHIM_DETERMINISM')
    _det = True if _det_env is None else (_det_env == '1')
    if _det:
        tf.config.experimental.enable_op_determinism()
    tf.random.set_seed(seed)
    shard = None
    _sh = os.environ.get('SHIM_SHARD')
    if _sh:
        _i, _n = _sh.split('/')
        shard = (int(_i), int(_n))
        if not (0 <= shard[0] < shard[1]):
            raise SystemExit('SHIM_SHARD=%s: need 0 <= i < N' % _sh)
    it = iter(build_imagenet_iter(split, batch, training, training, shard))
    _RES = _TRAIN_SIZE if training else _IMG_SIZE
    flat = 3 * _RES * _RES
    nclasses = int(os.environ.get('SHIM_NCLASSES', '0'))
    def _targets(y):
        if nclasses <= 0:
            return np.ascontiguousarray(y, dtype=np.int32)
        yi = np.asarray(y, dtype=np.int64).reshape(-1)
        t = np.zeros((yi.shape[0], nclasses), dtype=np.float32)
        ok = (yi >= 0) & (yi < nclasses)
        t[np.arange(yi.shape[0])[ok], yi[ok]] = 1.0
        return np.ascontiguousarray(t, dtype=np.float32)
    _MIX_MODE = os.environ.get('SHIM_MIX', 'off').strip().lower()
    _MIX_A = float(os.environ.get('SHIM_MIXUP_ALPHA', '0.100000'))
    _CUT_A = float(os.environ.get('SHIM_CUTMIX_ALPHA', '1.000000'))
    if _MIX_MODE not in ('off', 'mixup', 'cutmix', 'both'):
        raise SystemExit('SHIM_MIX=%s: expected off|mixup|cutmix|both' % _MIX_MODE)
    _MIX_ON = (_MIX_MODE != 'off') and training
    if _MIX_ON and nclasses <= 0:
        raise SystemExit('SHIM_MIX=%s needs SHIM_NCLASSES>0: a mixed target is a distribution '
                         'and wire v1 carries int32 hard labels' % _MIX_MODE)
    def _mix(x, t, step):
        # Returns (x, t) UNTOUCHED when off — the identity, not a copy, so the v1/v2 digests
        # are byte-for-byte what they were before mixing existed. Also the path the VALIDATION
        # split always takes, whatever SHIM_MIX says.
        if not _MIX_ON:
            return x, t
        B = t.shape[0]
        # ⚠ Seeded from (SHIM_SEED, step), like `augSeed`: an unseeded or wall-clock-seeded
        # draw makes the run unreproducible and breaks every gate that replays a batch.
        rng = np.random.default_rng([_SHIM_SEED, step])
        # `both` alternates per step, matching the reference's `if _global_step % 2 == 0`.
        cut = (_MIX_MODE == 'cutmix') or (_MIX_MODE == 'both' and (step % 2) == 1)
        if not cut:
            lam = np.float32(rng.beta(_MIX_A, _MIX_A))
            xm = lam * x + (np.float32(1.0) - lam) * np.flip(x, 0)
            tm = lam * t + (np.float32(1.0) - lam) * np.flip(t, 0)
            return (np.ascontiguousarray(xm, dtype=np.float32),
                    np.ascontiguousarray(tm, dtype=np.float32))
        H = W = _RES
        lam = float(rng.beta(_CUT_A, _CUT_A))
        x4 = x.reshape(B, 3, H, W)
        c = np.sqrt(1.0 - lam)
        cw = int(c * W); ch = int(c * H)
        cx = int(rng.integers(0, W)); cy = int(rng.integers(0, H))
        x1 = int(np.clip(cx - cw // 2, 0, W)); x2 = int(np.clip(cx + cw // 2, 0, W))
        y1c = int(np.clip(cy - ch // 2, 0, H)); y2c = int(np.clip(cy + ch // 2, 0, H))
        mask = np.zeros((H, W), dtype=np.float32)
        mask[y1c:y2c, x1:x2] = np.float32(1.0)
        x4m = x4 * (np.float32(1.0) - mask) + np.flip(x4, 0) * mask
        # ⚠ λ is re-derived from the ACTUAL pasted area, not from the draw — the box is clipped
        # at the border, so the two differ and the label must follow the pixels.
        lam_adj = np.float32(1.0 - float(mask.sum()) / float(H * W))
        tm = lam_adj * t + (np.float32(1.0) - lam_adj) * np.flip(t, 0)
        return (np.ascontiguousarray(x4m.reshape(B, -1), dtype=np.float32),
                np.ascontiguousarray(tm, dtype=np.float32))
    def _emit(x, y, step):
        return _mix(np.ascontiguousarray(x, dtype=np.float32), _targets(y), step)
    if hash_n:
        h = hashlib.sha256()
        for i, (x, y) in enumerate(it):
            if i >= hash_n: break
            xo, to = _emit(x, y, i)
            h.update(to.tobytes())
            h.update(xo.tobytes())
        sys.stderr.write('SHIM_HASH %d batches seed=%d split=%s mix=%s: %s\n'
                         % (hash_n, seed, split, _MIX_MODE if _MIX_ON else 'off',
                            h.hexdigest()))
        return
    out = sys.stdout.buffer
    out.write(b'LMSH')
    if nclasses > 0:
        out.write(np.array([4, batch, flat, nclasses], dtype=np.int32).tobytes())
    else:
        out.write(np.array([3, batch, flat], dtype=np.int32).tobytes())
    out.flush()
    for i, (x, y) in enumerate(it):
        xo, to = _emit(x, y, i)
        out.write(np.array([to.shape[0]], dtype=np.int32).tobytes())
        out.write(to.tobytes())
        out.write(xo.tobytes())
        out.flush()

if __name__ == '__main__':
    try:
        _main()
    except BrokenPipeError:
        # The consumer stopped (finished its epoch, or died). Exit quietly rather than
        # dumping a traceback that looks like a data-pipeline failure.
        try: sys.stdout.close()
        except Exception: pass
